{"src/exportCsv.mjs":"/**
 * 将对象数组转换为 CSV 字符串，便于在表格软件中打开。
 *
 * 设计要点：
 * - 字段名取自所有行键的并集，保持首次出现顺序，保证列稳定。
 * - 单元格内容来自外部填写，按 RFC 4180 规则转义：
 *   含逗号、双引号、换行（\r 或 \n）或首尾空白的值用双引号包裹，
 *   内部双引号加倍。
 * - 对以 = + - @ 等开头的文本做防公式注入处理（前置单引号），
 *   避免在表格软件中被当作公式执行；纯数字/布尔/null 不处理。
 * - 行分隔符使用 \r\n，兼容主流表格软件。
 * - 无行时返回空字符串；有行但无字段时返回空字符串。
 *
 * @param {Array<Object>} rows 对象数组
 * @returns {string} 可用于下载的 CSV 字符串
 */
export function exportCsv(rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    return "";
  }

  const columns = [];
  const seen = new Set();
  for (const row of rows) {
    if (row === null || typeof row !== "object") {
      continue;
    }
    for (const key of Object.keys(row)) {
      if (!seen.has(key)) {
        seen.add(key);
        columns.push(key);
      }
    }
  }

  if (columns.length === 0) {
    return "";
  }

  const lines = [columns.map(formatCell).join(",")];
  for (const row of rows) {
    const source = row !== null && typeof row === "object" ? row : {};
    lines.push(columns.map((key) => formatCell(source[key])).join(","));
  }

  return lines.join("\r\n");
}

function formatCell(value) {
  if (value === null || value === undefined) {
    return "";
  }

  let text;
  if (typeof value === "string") {
    text = value;
  } else if (typeof value === "number" || typeof value === "bigint") {
    text = String(value);
  } else if (typeof value === "boolean") {
    text = value ? "true" : "false";
  } else if (value instanceof Date) {
    text = Number.isNaN(value.getTime()) ? "" : value.toISOString();
  } else {
    try {
      text = JSON.stringify(value);
    } catch (err) {
      text = String(value);
    }
    if (text === undefined) {
      text = "";
    }
  }

  if (typeof value === "string" && isFormulaLike(text)) {
    text = "'" + text;
  }

  if (/[",\r\n]/.test(text) || /^\s|\s$/.test(text)) {
    return '"' + text.replace(/"/g, '""') + '"';
  }

  return text;
}

function isFormulaLike(text) {
  return /^[=+\-@\t\r]/.test(text);
}
